function LookupTorahVerse(globalIdx) {
  const idx = globalIdx | 0;
  const rows = TORAH_VERSE_MAP;
  if (!rows.length || idx < 0 || idx >= TORAH_TEXT.length) return null;
  let lo = 0;
  let hi = rows.length - 1;
  let hit = 0;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (rows[mid][0] <= idx) {
      hit = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  const row = rows[hit];
  const book = TORAH_BOOK_OFFSETS[row[1]];
  const end = (hit + 1 < rows.length) ? rows[hit + 1][0] : TORAH_TEXT.length;
  return {
    index: idx,
    bookKey: book.key,
    bookLabel: book.label,
    chapter: row[2],
    verse: row[3],
    start: row[0],
    end,
    reference: book.label + ' ' + row[2] + ':' + row[3]
  };
}

function LookupTorahVerseSpan(indices) {
  const list = Array.isArray(indices) ? indices : [indices];
  const refs = [];
  const seen = {};
  for (let i = 0; i < list.length; i++) {
    const v = LookupTorahVerse(list[i]);
    if (!v || seen[v.reference]) continue;
    seen[v.reference] = true;
    refs.push(v);
  }
  if (!refs.length) return '';
  if (refs.length === 1) return refs[0].reference;
  return refs[0].reference + ' → ' + refs[refs.length - 1].reference;
}

